//! Bounded file material owned by the original final-holdout provider.
//!
//! The host supplies an authorized regular file whose exact bytes were bound
//! into the frozen plan. The shared OS lock coordinates cooperating writers;
//! pathname admission, permissions, provenance and independent row collection
//! remain host responsibilities. Transfer the open file description exclusively:
//! do not retain writable duplicates or mutate the file outside this owner.
//! No decoded rows leave this type without the original runner's one-shot
//! post-consumption permit. This type does not issue roles or authenticate data.

use std::error::Error as StdError;
use std::fmt;
use std::fs::File;
use std::fs::TryLockError;
use std::io;
use std::io::Read;
use std::io::Seek;
use std::io::SeekFrom;

use codex_hepta_types::Digest32;

use super::FinalHoldoutProviderV1;
use super::OriginalFinalHoldoutReleasePermitV1;
use super::ProductFrozenEvaluationPlanV1;
use super::ProductProviderErrorV1;
use super::TemporalComparisonInputsV1;
use crate::FinalHoldoutJournalReceiptV1;
use crate::HoldoutUseDispositionV1;

#[path = "product_holdout_file_codec.rs"]
mod codec;

pub use codec::encode_file_final_holdout_material_v1;

const MAX_MATERIAL_BYTES: u64 = 32 * 1024 * 1024;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum FileFinalHoldoutErrorV1 {
    Binding,
    NotRegular,
    Busy,
    Capacity,
    Corrupt,
    Io(io::ErrorKind),
}

impl fmt::Display for FileFinalHoldoutErrorV1 {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(formatter, "{self:?}")
    }
}
impl StdError for FileFinalHoldoutErrorV1 {}

type FileError = FileFinalHoldoutErrorV1;

struct HeldMaterialFile(File);

impl Drop for HeldMaterialFile {
    fn drop(&mut self) {
        let _ = self.0.unlock();
    }
}

/// The supplied plan and material are data inputs, not credentials. There is no
/// receipt-only release, public permit constructor, File getter or rearm API.
pub struct LockedFileFinalHoldoutProviderV1 {
    material_file: HeldMaterialFile,
    expected_product: ProductFrozenEvaluationPlanV1,
    material_length: u64,
    release_attempted: bool,
}

impl LockedFileFinalHoldoutProviderV1 {
    pub fn open(file: File, expected: &ProductFrozenEvaluationPlanV1) -> Result<Self, FileError> {
        expected
            .validate_integrity()
            .map_err(|_| FileError::Binding)?;
        let metadata = File::metadata(&file).map_err(io_error)?;
        if !metadata.is_file() {
            return Err(FileError::NotRegular);
        }
        File::try_lock_shared(&file).map_err(|error| match error {
            TryLockError::WouldBlock => FileError::Busy,
            TryLockError::Error(error) => io_error(error),
        })?;
        let material_file = HeldMaterialFile(file);
        let material_length = File::metadata(&material_file.0).map_err(io_error)?.len();
        if material_length == 0 || material_length > MAX_MATERIAL_BYTES {
            return Err(FileError::Capacity);
        }
        let mut provider = Self {
            material_file,
            expected_product: expected.clone(),
            material_length,
            release_attempted: false,
        };
        provider.require_original_material()?;
        Ok(provider)
    }

    fn require_original_material(&mut self) -> Result<(), FileError> {
        let file: &mut File = &mut self.material_file.0;
        if File::metadata(file).map_err(io_error)?.len() != self.material_length {
            return Err(FileError::Corrupt);
        }
        Seek::seek(file, SeekFrom::Start(0)).map_err(io_error)?;
        let digest = Digest32::of_reader(&mut *file, MAX_MATERIAL_BYTES).map_err(io_error)?;
        if File::metadata(file).map_err(io_error)?.len() != self.material_length
            || digest != self.expected_product.frozen_plan.final_holdout_digest
        {
            return Err(FileError::Corrupt);
        }
        Ok(())
    }

    fn read_original_material(&mut self) -> Result<TemporalComparisonInputsV1, FileError> {
        let file: &mut File = &mut self.material_file.0;
        if File::metadata(file).map_err(io_error)?.len() != self.material_length {
            return Err(FileError::Corrupt);
        }
        Seek::seek(file, SeekFrom::Start(0)).map_err(io_error)?;
        let mut bytes = Vec::new();
        Read::take(&mut *file, MAX_MATERIAL_BYTES + 1)
            .read_to_end(&mut bytes)
            .map_err(io_error)?;
        if bytes.len() as u64 != self.material_length
            || File::metadata(file).map_err(io_error)?.len() != self.material_length
            || Digest32::of_bytes(&bytes)
                != self.expected_product.frozen_plan.final_holdout_digest
        {
            return Err(FileError::Corrupt);
        }
        codec::decode_original_material(&bytes, &self.expected_product.frozen_plan)
    }
}

impl FinalHoldoutProviderV1 for LockedFileFinalHoldoutProviderV1 {
    fn manifest_digest(&mut self) -> Result<Digest32, ProductProviderErrorV1> {
        if self.release_attempted {
            return Err(ProductProviderErrorV1::Rejected);
        }
        self.require_original_material().map_err(provider_error)?;
        Ok(self.expected_product.frozen_plan.final_holdout_digest)
    }

    fn release_after_consumption(
        &mut self,
        _receipt: &FinalHoldoutJournalReceiptV1,
    ) -> Result<TemporalComparisonInputsV1, ProductProviderErrorV1> {
        // A copied public receipt is not the original call's release permit.
        Err(ProductProviderErrorV1::Rejected)
    }

    fn release_original_consumption(
        &mut self,
        permit: OriginalFinalHoldoutReleasePermitV1<'_>,
    ) -> Result<TemporalComparisonInputsV1, ProductProviderErrorV1> {
        if std::mem::replace(&mut self.release_attempted, true) {
            return Err(ProductProviderErrorV1::Rejected);
        }
        let frozen = &self.expected_product.frozen_plan;
        if permit.plan != &self.expected_product
            || permit.receipt.disposition != HoldoutUseDispositionV1::Recorded
            || permit.receipt.use_receipt.disposition != HoldoutUseDispositionV1::Recorded
            || permit.receipt.sequence == 0
            || permit.receipt.record_digest.is_zero()
            || permit.receipt.head_digest.is_zero()
            || permit.receipt.authority.grants_any()
            || permit.receipt.use_receipt.authority.grants_any()
            || permit.receipt.use_receipt.plan_digest != frozen.plan_digest
            || permit.receipt.use_receipt.holdout_digest != frozen.final_holdout_digest
        {
            return Err(ProductProviderErrorV1::Rejected);
        }
        self.read_original_material().map_err(provider_error)
    }
}

fn io_error(error: io::Error) -> FileError {
    FileError::Io(error.kind())
}

fn provider_error(error: FileError) -> ProductProviderErrorV1 {
    match error {
        FileError::Busy | FileError::Io(_) => ProductProviderErrorV1::Unavailable,
        FileError::Binding | FileError::NotRegular | FileError::Capacity | FileError::Corrupt => {
            ProductProviderErrorV1::Rejected
        }
    }
}

//! Exact data encoding for a held final-holdout file. No signer or owner is
//! reconstructed by decoding these bytes; original runner validation still runs.

use codex_hepta_types::Digest32;
use codex_hepta_types::FixedQ32;
use codex_hepta_types::ProbabilityQ32;
use codex_hepta_types::StableId;

use super::FileError;
use super::MAX_MATERIAL_BYTES;
use crate::ClusterAssignment;
use crate::CrossFoldPlanReceiptV1;
use crate::HeldOutTarget;
use crate::OpeAction;
use crate::OpeRow;
use crate::OutcomeTrainingSample;
use crate::TemporalComparisonInputsV1;

const MAGIC: &[u8; 8] = b"HPFHMT01";
const MAX_ROWS: usize = 100_000;
const MAX_ACTIONS: usize = 128;
const MAX_IDS: usize = 1_000_000;

/// Encode actual supplied material. Hash the returned exact bytes into the
/// original plan before holdout observation. This pure codec creates neither
/// observations nor signatures, and grants no permission to release a file.
pub fn encode_file_final_holdout_material_v1(
    objective_digest: Digest32,
    dataset_digest: Digest32,
    final_holdout_window_id: &StableId,
    inputs: &TemporalComparisonInputsV1,
) -> Result<Vec<u8>, FileError> {
    if objective_digest.is_zero() || dataset_digest.is_zero() {
        return Err(FileError::Binding);
    }
    let mut writer = Writer(MAGIC.to_vec());
    writer.bytes(objective_digest.as_array())?;
    writer.bytes(dataset_digest.as_array())?;
    writer.id(final_holdout_window_id)?;
    writer.count(inputs.training.len(), MAX_ROWS)?;
    for row in &inputs.training {
        for id in [
            &row.decision_id,
            &row.principal_lineage,
            &row.episode_lineage,
            &row.window_id,
            &row.action_id,
        ] {
            writer.id(id)?;
        }
        writer.bytes(&row.outcome.raw().to_be_bytes())?;
        writer.bytes(&row.observed_at.to_be_bytes())?;
        writer.bytes(row.evidence_digest.as_array())?;
    }
    writer.count(inputs.targets.len(), MAX_ROWS)?;
    for row in &inputs.targets {
        for id in [
            &row.decision_id,
            &row.principal_lineage,
            &row.episode_lineage,
            &row.window_id,
        ] {
            writer.id(id)?;
        }
        writer.bytes(&row.decision_at.to_be_bytes())?;
        writer.ids(&row.actions, MAX_ACTIONS)?;
    }
    for rows in [&inputs.candidate_observations, &inputs.baseline_observations] {
        writer.count(rows.len(), MAX_ROWS)?;
        for row in rows {
            writer.id(&row.decision_id)?;
            writer.id(&row.chosen_action)?;
            writer.bytes(&[u8::from(row.complete_candidates)])?;
            writer.count(row.actions.len(), MAX_ACTIONS)?;
            for action in &row.actions {
                writer.id(&action.action_id)?;
                writer.bytes(&action.behavior_probability.raw().to_be_bytes())?;
                writer.bytes(&action.evaluation_probability.raw().to_be_bytes())?;
                writer.bytes(&action.predicted_outcome.raw().to_be_bytes())?;
            }
            match row.finalized_outcome {
                None => writer.bytes(&[0])?,
                Some(value) => {
                    writer.bytes(&[1])?;
                    writer.bytes(&value.raw().to_be_bytes())?;
                }
            }
            writer.bytes(&row.outcome_observed_at.to_be_bytes())?;
            writer.bytes(row.outcome_evidence.as_array())?;
            writer.bytes(row.outcome_model_evidence.as_array())?;
        }
    }
    writer.count(inputs.assignments.len(), MAX_ROWS)?;
    for row in &inputs.assignments {
        writer.id(&row.decision_id)?;
        writer.id(&row.cluster_id)?;
    }
    writer.ids(&inputs.snapshot_ids, MAX_IDS)?;
    writer.ids(&inputs.future_window_ids, MAX_IDS)?;
    Ok(writer.0)
}

pub(super) fn decode_original_material(
    bytes: &[u8],
    frozen: &CrossFoldPlanReceiptV1,
) -> Result<TemporalComparisonInputsV1, FileError> {
    if bytes.len() as u64 > MAX_MATERIAL_BYTES {
        return Err(FileError::Capacity);
    }
    let mut reader = Reader(bytes);
    if reader.take(8)? != MAGIC
        || reader.digest()? != frozen.objective_digest
        || reader.digest()? != frozen.dataset_digest
        || reader.id()? != frozen.final_holdout_window_id
    {
        return Err(FileError::Binding);
    }
    let count = reader.count(MAX_ROWS)?;
    let mut training = Vec::with_capacity(count);
    for _ in 0..count {
        training.push(OutcomeTrainingSample {
            decision_id: reader.id()?,
            principal_lineage: reader.id()?,
            episode_lineage: reader.id()?,
            window_id: reader.id()?,
            action_id: reader.id()?,
            outcome: reader.fixed()?,
            observed_at: reader.u64()?,
            evidence_digest: reader.digest()?,
        });
    }
    let count = reader.count(MAX_ROWS)?;
    let mut targets = Vec::with_capacity(count);
    for _ in 0..count {
        targets.push(HeldOutTarget {
            decision_id: reader.id()?,
            principal_lineage: reader.id()?,
            episode_lineage: reader.id()?,
            window_id: reader.id()?,
            decision_at: reader.u64()?,
            actions: reader.ids(MAX_ACTIONS)?,
        });
    }
    let candidate_observations = reader.observations()?;
    let baseline_observations = reader.observations()?;
    let count = reader.count(MAX_ROWS)?;
    let mut assignments = Vec::with_capacity(count);
    for _ in 0..count {
        assignments.push(ClusterAssignment {
            decision_id: reader.id()?,
            cluster_id: reader.id()?,
        });
    }
    let snapshot_ids = reader.ids(MAX_IDS)?;
    let future_window_ids = reader.ids(MAX_IDS)?;
    if !reader.0.is_empty() {
        return Err(FileError::Corrupt);
    }
    Ok(TemporalComparisonInputsV1 {
        training,
        targets,
        candidate_observations,
        baseline_observations,
        assignments,
        snapshot_ids,
        future_window_ids,
    })
}

struct Writer(Vec<u8>);

impl Writer {
    fn bytes(&mut self, bytes: &[u8]) -> Result<(), FileError> {
        if self
            .0
            .len()
            .checked_add(bytes.len())
            .is_none_or(|length| length as u64 > MAX_MATERIAL_BYTES)
        {
            return Err(FileError::Capacity);
        }
        self.0.extend_from_slice(bytes);
        Ok(())
    }

    fn count(&mut self, count: usize, limit: usize) -> Result<(), FileError> {
        if count > limit {
            return Err(FileError::Capacity);
        }
        self.bytes(&(count as u32).to_be_bytes())
    }

    fn id(&mut self, value: &StableId) -> Result<(), FileError> {
        let bytes = value.as_str().as_bytes();
        if bytes.is_empty() || bytes.len() > 128 {
            return Err(FileError::Binding);
        }
        self.bytes(&(bytes.len() as u16).to_be_bytes())?;
        self.bytes(bytes)
    }

    fn ids(&mut self, ids: &[StableId], limit: usize) -> Result<(), FileError> {
        self.count(ids.len(), limit)?;
        for id in ids {
            self.id(id)?;
        }
        Ok(())
    }
}

struct Reader<'a>(&'a [u8]);

impl Reader<'_> {
    fn take(&mut self, count: usize) -> Result<&[u8], FileError> {
        let (head, tail) = self.0.split_at_checked(count).ok_or(FileError::Corrupt)?;
        self.0 = tail;
        Ok(head)
    }

    fn u64(&mut self) -> Result<u64, FileError> {
        Ok(u64::from_be_bytes(
            self.take(8)?.try_into().map_err(|_| FileError::Corrupt)?,
        ))
    }

    fn fixed(&mut self) -> Result<FixedQ32, FileError> {
        Ok(FixedQ32::from_raw(i64::from_be_bytes(
            self.take(8)?.try_into().map_err(|_| FileError::Corrupt)?,
        )))
    }

    fn probability(&mut self) -> Result<ProbabilityQ32, FileError> {
        ProbabilityQ32::from_raw(self.u64()?).map_err(|_| FileError::Corrupt)
    }

    fn digest(&mut self) -> Result<Digest32, FileError> {
        Ok(Digest32::from_array(
            self.take(32)?.try_into().map_err(|_| FileError::Corrupt)?,
        ))
    }

    fn count(&mut self, limit: usize) -> Result<usize, FileError> {
        let count = u32::from_be_bytes(
            self.take(4)?.try_into().map_err(|_| FileError::Corrupt)?,
        ) as usize;
        if count > limit || count > self.0.len() {
            return Err(FileError::Capacity);
        }
        Ok(count)
    }

    fn id(&mut self) -> Result<StableId, FileError> {
        let count = u16::from_be_bytes(
            self.take(2)?.try_into().map_err(|_| FileError::Corrupt)?,
        ) as usize;
        if !(1..=128).contains(&count) {
            return Err(FileError::Corrupt);
        }
        let name = std::str::from_utf8(self.take(count)?).map_err(|_| FileError::Corrupt)?;
        StableId::new(name).map_err(|_| FileError::Corrupt)
    }

    fn ids(&mut self, limit: usize) -> Result<Vec<StableId>, FileError> {
        let count = self.count(limit)?;
        let mut ids = Vec::with_capacity(count);
        for _ in 0..count {
            ids.push(self.id()?);
        }
        Ok(ids)
    }

    fn observations(&mut self) -> Result<Vec<OpeRow>, FileError> {
        let count = self.count(MAX_ROWS)?;
        let mut rows = Vec::with_capacity(count);
        for _ in 0..count {
            let decision_id = self.id()?;
            let chosen_action = self.id()?;
            let complete_candidates = match self.take(1)?[0] {
                0 => false,
                1 => true,
                _ => return Err(FileError::Corrupt),
            };
            let action_count = self.count(MAX_ACTIONS)?;
            let mut actions = Vec::with_capacity(action_count);
            for _ in 0..action_count {
                actions.push(OpeAction {
                    action_id: self.id()?,
                    behavior_probability: self.probability()?,
                    evaluation_probability: self.probability()?,
                    predicted_outcome: self.fixed()?,
                });
            }
            let finalized_outcome = match self.take(1)?[0] {
                0 => None,
                1 => Some(self.fixed()?),
                _ => return Err(FileError::Corrupt),
            };
            rows.push(OpeRow {
                decision_id,
                chosen_action,
                complete_candidates,
                actions,
                finalized_outcome,
                outcome_observed_at: self.u64()?,
                outcome_evidence: self.digest()?,
                outcome_model_evidence: self.digest()?,
            });
        }
        Ok(rows)
    }
}

//! Durable publication of the exact qualification produced by the runner.
//!
//! This is a data store, not an evaluator or receipt factory. The host supplies
//! a distinct authorized evidence file, its namespace binding and independently
//! retained recovery minimum. The wrapped original file store retains its OS
//! lock, append/fsync, immutable completion and fail-closed recovery semantics.
//! Namespace admission, directory durability and external anchor retention
//! remain host duties. No precomputed qualification is loaded as an execution.

use std::fs::File;

use codex_hepta_types::Digest32;
use codex_hepta_types::StableId;

use crate::IndependentEvaluationDispositionV1;
use crate::LockedFileProductEvaluationExecutionErrorV1;
use crate::LockedFileProductEvaluationExecutionStoreV1;
use crate::MAX_PRODUCT_EVALUATION_EXECUTION_BYTES_V1;
use crate::ProductEvaluationExecutionAnchorV1;
use crate::ProductEvaluationExecutionClaimV1;
use crate::ProductEvaluationExecutionKeyV1;
use crate::ProductEvaluationExecutionStateV1;
use crate::ProductEvaluationExecutionStoreErrorV1;
use crate::ProductEvaluationExecutionStoreV1;
use crate::ProductEvidenceSinkErrorV1;
use crate::ProductQualificationEvidenceSinkV1;
use crate::SignedEvaluationDecisionV1;

type SinkError = ProductEvidenceSinkErrorV1;
type FileError = LockedFileProductEvaluationExecutionErrorV1;
type StoreError = ProductEvaluationExecutionStoreErrorV1;

/// Owns a separate evidence namespace. There is no constructor accepting an
/// arbitrary store implementation, claimed digest, completed receipt or callback.
pub struct LockedFileProductQualificationEvidenceSinkV1 {
    publication_store: LockedFileProductEvaluationExecutionStoreV1,
    owner_binding: Digest32,
    terminal_uncertainty: bool,
}

impl LockedFileProductQualificationEvidenceSinkV1 {
    pub fn create(file: File, owner_binding: Digest32) -> Result<Self, FileError> {
        let binding = evidence_namespace(owner_binding)?;
        let publication_store =
            LockedFileProductEvaluationExecutionStoreV1::create(file, binding)?;
        Ok(Self {
            publication_store,
            owner_binding,
            terminal_uncertainty: false,
        })
    }

    pub fn recover(
        file: File,
        owner_binding: Digest32,
        minimum: ProductEvaluationExecutionAnchorV1,
    ) -> Result<Self, FileError> {
        let binding = evidence_namespace(owner_binding)?;
        let publication_store =
            LockedFileProductEvaluationExecutionStoreV1::recover(file, binding, minimum)?;
        Ok(Self {
            publication_store,
            owner_binding,
            terminal_uncertainty: false,
        })
    }

    #[must_use]
    pub fn anchor(&self) -> ProductEvaluationExecutionAnchorV1 {
        self.publication_store.anchor()
    }

    /// Read the exact committed data. This does not reconstruct a sealed
    /// ProductQualificationReceiptV1, reauthenticate a role or grant eligibility.
    pub fn readback(
        &mut self,
        execution_digest: Digest32,
        decision: &SignedEvaluationDecisionV1,
    ) -> Result<Digest32, SinkError> {
        if self.terminal_uncertainty {
            return Err(SinkError::Indeterminate);
        }
        let payload = encode_decision(self.owner_binding, execution_digest, decision)?;
        let key = publication_key(self.owner_binding, execution_digest)?;
        let state = ProductEvaluationExecutionStoreV1::readback(
            &mut self.publication_store,
            &key,
        )
        .map_err(store_error)?;
        match state {
            ProductEvaluationExecutionStateV1::Completed(bytes) if bytes == payload => {
                Ok(publication_digest(&payload))
            }
            ProductEvaluationExecutionStateV1::Completed(_) => Err(SinkError::Rejected),
            ProductEvaluationExecutionStateV1::Pending => {
                self.terminal_uncertainty = true;
                Err(SinkError::Indeterminate)
            }
        }
    }
}

impl ProductQualificationEvidenceSinkV1 for LockedFileProductQualificationEvidenceSinkV1 {
    fn persist(
        &mut self,
        execution_digest: Digest32,
        decision: &SignedEvaluationDecisionV1,
    ) -> Result<Digest32, SinkError> {
        if self.terminal_uncertainty {
            return Err(SinkError::Indeterminate);
        }
        let payload = encode_decision(self.owner_binding, execution_digest, decision)?;
        let key = publication_key(self.owner_binding, execution_digest)?;
        let claim = ProductEvaluationExecutionStoreV1::claim(
            &mut self.publication_store,
            &key,
        )
        .map_err(store_error)?;
        match claim {
            ProductEvaluationExecutionClaimV1::Existing(
                ProductEvaluationExecutionStateV1::Completed(bytes),
            ) => {
                if bytes != payload {
                    return Err(SinkError::Rejected);
                }
            }
            ProductEvaluationExecutionClaimV1::Existing(
                ProductEvaluationExecutionStateV1::Pending,
            ) => {
                self.terminal_uncertainty = true;
                return Err(SinkError::Indeterminate);
            }
            ProductEvaluationExecutionClaimV1::Claimed => {
                if ProductEvaluationExecutionStoreV1::complete(
                    &mut self.publication_store,
                    &key,
                    &payload,
                )
                .is_err()
                {
                    self.terminal_uncertainty = true;
                    return Err(SinkError::Indeterminate);
                }
            }
        }
        // Retain the original store's post-fsync readback and metadata check.
        // Once a claim could exist, failure is terminal, never a fresh retry.
        match ProductEvaluationExecutionStoreV1::readback(
            &mut self.publication_store,
            &key,
        ) {
            Ok(ProductEvaluationExecutionStateV1::Completed(bytes)) if bytes == payload => {
                Ok(publication_digest(&payload))
            }
            Ok(_) | Err(_) => {
                self.terminal_uncertainty = true;
                Err(SinkError::Indeterminate)
            }
        }
    }
}

fn evidence_namespace(owner_binding: Digest32) -> Result<Digest32, FileError> {
    if owner_binding.is_zero() {
        return Err(FileError::Binding);
    }
    Ok(Digest32::of_parts(&[
        b"hepta.product-qualification.evidence-namespace.v1",
        owner_binding.as_array(),
    ]))
}

fn publication_key(
    owner_binding: Digest32,
    execution_digest: Digest32,
) -> Result<ProductEvaluationExecutionKeyV1, SinkError> {
    // One actual execution has one immutable terminal decision. Its evaluation
    // ID is committed in the payload and cannot select another publication key.
    let plan_id = StableId::new(execution_digest.to_string()).map_err(|_| SinkError::Rejected)?;
    Ok(ProductEvaluationExecutionKeyV1 {
        plan_id,
        binding_digest: Digest32::of_parts(&[
            b"hepta.product-qualification.evidence-key.v1",
            owner_binding.as_array(),
            execution_digest.as_array(),
        ]),
    })
}

fn encode_decision(
    owner_binding: Digest32,
    execution_digest: Digest32,
    signed: &SignedEvaluationDecisionV1,
) -> Result<Vec<u8>, SinkError> {
    let decision = &signed.decision;
    if owner_binding.is_zero()
        || execution_digest.is_zero()
        || decision.evidence_digest.is_zero()
        || signed.trust_digest.is_zero()
        || signed.authentication_digest.is_zero()
        || decision.authority.grants_any()
        || decision.failed_metrics.len() > 128
    {
        return Err(SinkError::Rejected);
    }
    let mut bytes = b"HPQLEV01".to_vec();
    bytes.extend_from_slice(owner_binding.as_array());
    bytes.extend_from_slice(execution_digest.as_array());
    for id in [
        &decision.evaluation_id,
        &decision.candidate_id,
        &decision.baseline_id,
    ] {
        put_id(&mut bytes, id)?;
    }
    bytes.push(match decision.disposition {
        IndependentEvaluationDispositionV1::EligibleForIndependentSelection => 0,
        IndependentEvaluationDispositionV1::Ineligible => 1,
        IndependentEvaluationDispositionV1::InsufficientEvidence => 2,
    });
    bytes.extend_from_slice(&(decision.failed_metrics.len() as u32).to_be_bytes());
    for id in &decision.failed_metrics {
        put_id(&mut bytes, id)?;
    }
    for digest in [
        decision.evidence_digest,
        signed.trust_digest,
        signed.authentication_digest,
    ] {
        bytes.extend_from_slice(digest.as_array());
    }
    if bytes.len() > MAX_PRODUCT_EVALUATION_EXECUTION_BYTES_V1 {
        return Err(SinkError::Rejected);
    }
    Ok(bytes)
}

fn put_id(bytes: &mut Vec<u8>, id: &StableId) -> Result<(), SinkError> {
    let value = id.as_str().as_bytes();
    if value.is_empty() || value.len() > 128 {
        return Err(SinkError::Rejected);
    }
    bytes.extend_from_slice(&(value.len() as u16).to_be_bytes());
    bytes.extend_from_slice(value);
    Ok(())
}

fn publication_digest(payload: &[u8]) -> Digest32 {
    Digest32::of_parts(&[
        b"hepta.product-qualification.durable-publication.v1",
        payload,
    ])
}

fn store_error(error: StoreError) -> SinkError {
    match error {
        StoreError::Unavailable => SinkError::Unavailable,
        StoreError::Indeterminate | StoreError::Corrupt => SinkError::Indeterminate,
        StoreError::Missing | StoreError::Conflict | StoreError::Rejected => SinkError::Rejected,
    }
}

